// Append newly built geo hubs to the committed geo hub files without regenerating the old ones
// (2026-10-24). scripts/build-geo-hubs.mjs rewrites all three files from the content agents'
// scratch outputs, and the 2026-10-02..08 outputs (and later hand fixes to the generated files)
// are not available to re-run, so new hubs are built into a separate --out directory and merged:
//
//   node scripts/build-geo-hubs.mjs --scratch <dir with only the new outputs> --out <tmp>
//   node scripts/geo-hubs-append.mjs <tmp>
//
// Refuses to overwrite an existing path. Appends to scripts/geo-hub-routes.mjs (GEO_HUB_ROUTES),
// src/data/geo-hubs.json (index) and src/data/geo-hubs-pages.json (full records).
import { readFileSync, writeFileSync } from 'fs';
import { join } from 'path';

const tmp = process.argv[2];
if (!tmp) { console.error('usage: node scripts/geo-hubs-append.mjs <build-geo-hubs --out dir>'); process.exit(1); }
const ROUTES = 'scripts/geo-hub-routes.mjs';
const INDEX = 'src/data/geo-hubs.json';
const PAGES = 'src/data/geo-hubs-pages.json';

const routesOf = (src) => JSON.parse(src.slice(src.indexOf('= [') + 2).replace(/;\s*$/, ''));
const cur = { routes: routesOf(readFileSync(ROUTES, 'utf8')), index: JSON.parse(readFileSync(INDEX, 'utf8')), pages: JSON.parse(readFileSync(PAGES, 'utf8')) };
const add = { routes: routesOf(readFileSync(join(tmp, ROUTES), 'utf8')), index: JSON.parse(readFileSync(join(tmp, INDEX), 'utf8')), pages: JSON.parse(readFileSync(join(tmp, PAGES), 'utf8')) };
const have = new Set(cur.index.map((x) => x.path));
const dup = add.index.filter((x) => have.has(x.path)).map((x) => x.path);
if (dup.length) { console.error(`refusing: already present: ${dup.join(', ')}`); process.exit(1); }
const routes = [...cur.routes, ...add.routes];
const index = [...cur.index, ...add.index];
const pages = [...cur.pages, ...add.pages];
const fam = index.reduce((m, v) => ((m[v.family] = (m[v.family] || 0) + 1), m), {});
writeFileSync(ROUTES, `// GENERATED by scripts/build-geo-hubs.mjs — do not hand-edit (new hubs appended by scripts/geo-hubs-append.mjs).
// ${routes.length} geo hub pages ${JSON.stringify(fam)}, ${new Date().toISOString()}.
export const GEO_HUB_ROUTES = ${JSON.stringify(routes, null, 1)};
`);
writeFileSync(INDEX, JSON.stringify(index, null, 1));
writeFileSync(PAGES, JSON.stringify(pages));
console.log(`appended ${add.index.length} geo hubs: ${add.index.map((x) => x.path).join(', ')} (now ${index.length})`);
